use codegen::CodeGenerator;
use core::usecases::CodeGeneratorPort;
use core::{DatabaseSchema, DomainError};

pub struct TypeScriptGenerator;

impl TypeScriptGenerator {
    #[must_use]
    pub const fn new() -> Self {
        Self
    }
}

impl Default for TypeScriptGenerator {
    fn default() -> Self {
        Self::new()
    }
}

impl CodeGenerator for TypeScriptGenerator {
    fn language(&self) -> &'static str {
        "typescript"
    }

    fn generate(&self, schema: &DatabaseSchema) -> Result<String, DomainError> {
        let mut lines = vec![
            "// Generated by Awesome Schema".to_owned(),
            "// TypeScript model generation stub — expand in future milestones".to_owned(),
            String::new(),
        ];

        for model in &schema.models {
            lines.push(format!("export type {} = {{", model.name));
            for field in &model.fields {
                let ts_type = map_field_type(&field.field_type);
                let optional = if field.optional { "?" } else { "" };
                lines.push(format!("  {}{optional}: {};", field.name, ts_type));
            }
            lines.push("};".to_owned());
            lines.push(String::new());
        }

        Ok(lines.join("\n"))
    }
}

impl CodeGeneratorPort for TypeScriptGenerator {
    fn generate(&self, schema: &DatabaseSchema) -> Result<String, DomainError> {
        CodeGenerator::generate(self, schema)
    }
}

fn map_field_type(field_type: &core::FieldType) -> String {
    match field_type {
        core::FieldType::String => "string".to_owned(),
        core::FieldType::Int | core::FieldType::Float => "number".to_owned(),
        core::FieldType::Bool => "boolean".to_owned(),
        core::FieldType::Datetime => "Date".to_owned(),
        core::FieldType::Object => "Record<string, unknown>".to_owned(),
        core::FieldType::Array(inner) => format!("{}[]", map_field_type(inner)),
        core::FieldType::RecordId(name) | core::FieldType::Model(name) => name.clone(),
        core::FieldType::Custom(value) => value.clone(),
    }
}
